def good(y):
    return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)


def bug1(y):
    return y % 4 == 0


def bug2(y):
    return y % 4 == 0 and y % 100 != 0


def bug3(y):
    return (y % 4 == 0 and y % 100 != 0) or y % 200 == 0


def tests(is_leap):
    assert is_leap(2024)
    assert not is_leap(2023)
    assert not is_leap(1900)
    assert is_leap(2000)
    assert not is_leap(1800)


impls = {"good": good, "bug1": bug1, "bug2": bug2, "bug3": bug3}
impl = impls[input().strip()]
try:
    tests(impl)
    print("PASS")
except AssertionError:
    print("FAIL")

